function h(string $v): string { return htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
function id(string $prefix): string { return $prefix . '-' . bin2hex(random_bytes(8)); }
function s(mixed $v, int $max=5000): string { $text=trim(is_scalar($v)?(string)$v:''); return function_exists('mb_substr') ? mb_substr($text,0,$max,'UTF-8') : substr($text,0,$max); }
function baseFields(): array {
    return [
      ['id'=>'field-type','key'=>'Type','label'=>'Type','type'=>'select','values'=>['Change','Compliance','Incident','Incident:Major','Invastigation','Operation&Maintenance','Problem','RfC','RMA','ServiceRequest','SPAM','Unclassified'],'required'=>true],
      ['id'=>'field-queue','key'=>'Queue','label'=>'To queue','type'=>'select','values'=>['Consulting','RMA','SPAM','Support'],'required'=>true],
      ['id'=>'field-service','key'=>'Service','label'=>'Service','type'=>'select','values'=>['Basic Support','Extra Support','Internal','Managed Service'],'required'=>true],
      ['id'=>'field-owner','key'=>'Owner','label'=>'Owner','type'=>'select','values'=>['$$Owner'],'required'=>true]
    ];
}
function freshData(): array { return ['configuration'=>['fields'=>baseFields(),'linkTypes'=>['Normal','ParentChild']],'masks'=>[]]; }
function normType(mixed $v): string { $x=s($v,30); if($x==='textarea')$x='text'; return in_array($x,['text','select','number','random'],true)?$x:'text'; }
function cleanValues(mixed $v): array {
    if (is_string($v)) $v=preg_split('/\R/u',$v) ?: [];
    if (!is_array($v)) return [];
    $out=[]; foreach(array_slice($v,0,200) as $x){$x=s($x,200);if($x!==''&&!in_array($x,$out,true))$out[]=$x;} return $out;
}
function migrate(array $raw): array {
    $cfg=$raw['configuration']??$raw['config']??[];
