    $oldFields=$cfg['fields']??$cfg['lists']??[];
    $fields=[];
    if (is_array($oldFields)) foreach(array_slice($oldFields,0,MAX_FIELDS) as $f){
      if(!is_array($f))continue; $key=s($f['key']??$f['technicalName']??$f['field']??$f['name']??'',100); if($key==='')continue;
      $fields[]=['id'=>s($f['id']??'',100)?:id('field'),'key'=>$key,'label'=>s($f['label']??$f['name']??$key,160),'type'=>normType($f['type']??'text'),'values'=>cleanValues($f['values']??$f['options']??[]),'required'=>(bool)($f['required']??in_array($key,['Queue','State','Priority'],true))];
    }
    $fixed=baseFields(); foreach($fixed as &$fixedField){foreach($fields as $oldField)if($oldField['key']===$fixedField['key']){if($fixedField['key']==='Owner'){$fixedField['type']='select';$fixedField['values']=['$$Owner'];}break;}} unset($fixedField); $fields=$fixed;
    $links=cleanValues($cfg['linkTypes']??$cfg['links']??['Normal','ParentChild']); if(!$links)$links=['Normal','ParentChild'];
    $masks=[];
    foreach(array_slice(is_array($raw['masks']??null)?$raw['masks']:[],0,MAX_MASKS) as $m){
      if(!is_array($m))continue; $vars=[];
      foreach(array_slice(is_array($m['variables']??null)?$m['variables']:[],0,MAX_VARIABLES) as $v){if(!is_array($v))continue;$name=s($v['name']??'',120);if($name==='')continue;$vars[]=['id'=>s($v['id']??'',100)?:id('variable'),'name'=>$name,'type'=>normType($v['type']??'text'),'values'=>cleanValues($v['values']??[]),'prefill'=>s($v['prefill']??$v['default']??'',5000),'minimum'=>isset($v['minimum'])&&$v['minimum']!==''?(float)$v['minimum']:null,'maximum'=>isset($v['maximum'])&&$v['maximum']!==''?(float)$v['maximum']:null,'required'=>(bool)($v['required']??false),'hidden'=>(bool)($v['hidden']??false)];}
      $steps=[]; foreach(array_slice(is_array($m['steps']??null)?$m['steps']:[],0,MAX_STEPS) as $st){if(!is_array($st))continue;$fields2=[];foreach(array_slice(is_array($st['fields']??null)?$st['fields']:[],0,MAX_FIELDS) as $sf){if(!is_array($sf))continue;$key=s($sf['key']??$sf['field']??$sf['technicalName']??$sf['name']??'',100);if($key==='')continue;$fields2[]=['id'=>s($sf['id']??'',100)?:id('step-field'),'key'=>$key,'value'=>s($sf['value']??'',5000),'enabled'=>(bool)($sf['enabled']??true)];}$ln=[];foreach(array_slice(is_array($st['links']??null)?$st['links']:[],0,20) as $l){if(!is_array($l))continue;$ln[]=['id'=>s($l['id']??'',100)?:id('link'),'object'=>s($l['object']??$l['objectType']??'Ticket',100),'type'=>s($l['type']??$l['linkType']??'Normal',100),'direction'=>s($l['direction']??'Target',40),'target'=>s($l['target']??'',5000)];}$steps[]=['id'=>s($st['id']??'',100)?:id('step'),'action'=>s($st['action']??'free',50),'subject'=>s($st['subject']??'',5000),'body'=>s($st['body']??$st['text']??'',20000),'fields'=>$fields2,'links'=>$ln,'meta'=>is_array($st['meta']??null)?$st['meta']:[]];}
      if(!$steps)$steps[]=['id'=>id('step'),'action'=>'ticket-create','subject'=>'','body'=>'','fields'=>[],'links'=>[],'meta'=>[]]; $steps[0]['action']='ticket-create';
      $masks[]=['id'=>s($m['id']??'',100)?:id('mask'),'name'=>s($m['name']??'Unbenannte Maske',160),'yamlName'=>s($m['yamlName']??'',160),'description'=>s($m['description']??'',1000),'published'=>true,'variables'=>$vars,'steps'=>$steps,'updatedAt'=>s($m['updatedAt']??'',40)?:date(DATE_ATOM)];
    }
    return ['configuration'=>['fields'=>$fields,'linkTypes'=>$links],'masks'=>$masks];
}
function loadData(): array {
    if(!file_exists(DATA_FILE)){saveData(freshData());return freshData();}
    $txt=file_get_contents(DATA_FILE); if($txt===false)throw new RuntimeException('masks.json konnte nicht gelesen werden.');
    try{$raw=json_decode($txt,true,512,JSON_THROW_ON_ERROR);}catch(JsonException){throw new RuntimeException('masks.json enthält ungültiges JSON. Die Datei wurde nicht verändert.');}
    if(!is_array($raw))throw new RuntimeException('masks.json besitzt kein gültiges Grundformat.'); return migrate($raw);
}
function saveData(array $data): void {
    $json=json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);
    $lock=fopen(DATA_FILE.'.lock','c'); if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Speichersperre konnte nicht gesetzt werden.');
    $tmp=DATA_FILE.'.tmp.'.bin2hex(random_bytes(4)); try{if(file_put_contents($tmp,$json."\n",LOCK_EX)===false)throw new RuntimeException('Temporäre Datei konnte nicht geschrieben werden.');if(!rename($tmp,DATA_FILE))throw new RuntimeException('masks.json konnte nicht atomar ersetzt werden.');}finally{if(file_exists($tmp))@unlink($tmp);flock($lock,LOCK_UN);fclose($lock);}
}
function postJson(): array { if((int)($_SERVER['CONTENT_LENGTH']??0)>MAX_POST_BYTES)throw new RuntimeException('POST-Daten sind zu groß.'); $raw=file_get_contents('php://input');$p=json_decode($raw?:'[]',true,512,JSON_THROW_ON_ERROR);if(!is_array($p))throw new RuntimeException('Ungültige Anfrage.');if(!hash_equals($_SESSION['csrf'],s($p['csrf']??'',128)))throw new RuntimeException('Ungültiges CSRF-Token.');return $p; }
function actionName(string $a): string {return ['ticket-create'=>'Ticket erstellen','ticket-edit'=>'Feld ändern','title-edit'=>'Titel ändern','note'=>'Textfeld','phone-in'=>'Phone in','phone-out'=>'Phone out','email-in'=>'Email in','email-out'=>'Email out','email'=>'E-Mail hinzufügen','phone'=>'Telefonartikel hinzufügen','customer'=>'Kunde ändern','queue'=>'Queue ändern','owner'=>'Besitzer ändern','responsible'=>'Verantwortlichen ändern','state'=>'Status ändern','priority'=>'Priorität ändern','type'=>'Typ ändern','service'=>'Service ändern','sla'=>'SLA ändern','field-set'=>'Feld setzen','link'=>'Verknüpfen','close'=>'Ticket schließen','free'=>'Freier Schritt'][$a]??'Freier Schritt';}

$error='';try{$data=loadData();}catch(Throwable $e){$data=freshData();$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'){
  header('Content-Type: application/json; charset=UTF-8');
  try{$p=postJson();$op=s($p['op']??'',30);$data=loadData();
    if($op==='save-config'){$c=is_array($p['configuration']??null)?$p['configuration']:[];$fields=[];foreach(array_slice(is_array($c['fields']??null)?$c['fields']:[],0,MAX_FIELDS) as $f){if(!is_array($f))continue;$key=s($f['key']??'',100);if($key==='')throw new RuntimeException('Jedes Feld benötigt einen Schlüssel.');$fields[]=['id'=>s($f['id']??'',100)?:id('field'),'key'=>$key,'label'=>s($f['label']??$key,160),'type'=>normType($f['type']??'text'),'values'=>cleanValues($f['values']??[]),'required'=>(bool)($f['required']??false)];}if(!$fields)throw new RuntimeException('Mindestens ein Znuny-Feld ist erforderlich.');$data['configuration']=['fields'=>$fields,'linkTypes'=>cleanValues($c['linkTypes']??[])];saveData($data);echo json_encode(['ok'=>true]);exit;}
    if($op==='save-mask'){$m=is_array($p['mask']??null)?$p['mask']:[];$mid=s($m['id']??'',100)?:id('mask');$name=s($m['name']??'',160);if($name==='')throw new RuntimeException('Der Maskenname ist erforderlich.');$clean=migrate(['configuration'=>$data['configuration'],'masks'=>[array_merge($m,['id'=>$mid,'name'=>$name,'published'=>true,'updatedAt'=>date(DATE_ATOM)])]])['masks'][0];$canonical=[];foreach(['Type','Queue','Service','Owner'] as $fixedKey){$foundField=null;foreach($clean['steps'][0]['fields'] as $stepField)if($stepField['key']===$fixedKey){$foundField=$stepField;break;}if($foundField===null)$foundField=['id'=>id('step-field'),'key'=>$fixedKey,'value'=>'','enabled'=>true];$foundField['enabled']=true;if($fixedKey==='Owner')$foundField['value']='$$Owner';$canonical[]=$foundField;}$clean['steps'][0]['fields']=$canonical;$found=false;foreach($data['masks'] as $i=>$old)if($old['id']===$mid){$data['masks'][$i]=$clean;$found=true;break;}if(!$found){if(count($data['masks'])>=MAX_MASKS)throw new RuntimeException('Maximale Maskenanzahl erreicht.');$data['masks'][]=$clean;}saveData($data);echo json_encode(['ok'=>true,'id'=>$mid]);exit;}
    if($op==='delete-mask'){$mid=s($p['id']??'',100);$data['masks']=array_values(array_filter($data['masks'],fn($m)=>$m['id']!==$mid));saveData($data);echo json_encode(['ok'=>true]);exit;}
    throw new RuntimeException('Unbekannte Aktion.');
  }catch(Throwable $e){http_response_code(400);echo json_encode(['ok'=>false,'error'=>$e->getMessage()],JSON_UNESCAPED_UNICODE);exit;}
}
