'use strict';
document.documentElement.dataset.theme=matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light';matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>document.documentElement.dataset.theme=e.matches?'dark':'light')
const CSRF=<?=json_encode($_SESSION['csrf'])?>, CONFIG=<?=json_encode($data['configuration'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>, PAGE=<?=json_encode($page)?>, CURRENT=<?=json_encode(isset($sel)?$sel:null,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>Array.from(r.querySelectorAll(q));
function el(tag,attrs={},text=''){const n=document.createElement(tag);Object.entries(attrs).forEach(([k,v])=>{if(k==='class')n.className=v;else if(k==='checked')n.checked=!!v;else if(k==='value')n.value=v??'';else if(k.startsWith('on'))n.addEventListener(k.slice(2),v);else n.setAttribute(k,String(v));});if(text!=='')n.textContent=text;return n}
function status(t,bad=false){const n=$('#status');n.textContent=t;n.style.background=bad?'#8f2525':'#24313a';n.classList.remove('hidden');setTimeout(()=>n.classList.add('hidden'),3500)}
async function api(payload){const r=await fetch(location.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload,csrf:CSRF})});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Fehler');return j}
$('#burger').addEventListener('click',()=>{const m=$('#menu'),show=m.classList.toggle('hidden');$('#burger').setAttribute('aria-expanded',String(!show))});document.addEventListener('click',e=>{if(!e.target.closest('.top')&&!e.target.closest('#menu'))$('#menu').classList.add('hidden');if(!e.target.closest('.context-menu'))document.querySelectorAll('.context-menu').forEach(n=>n.remove())});
$$('.delete-mask').forEach(b=>b.addEventListener('click',async()=>{if(!confirm('Diese Maske wirklich löschen?'))return;try{await api({op:'delete-mask',id:b.dataset.id});location.reload()}catch(e){status(e.message,true)}}));
const types=['text','select','number','random'];
function labeled(label,node,cls='c3'){const d=el('div',{class:cls});d.append(el('label',{},label),node);return d}
function select(options,value){const n=el('select');options.forEach(x=>n.append(el('option',{value:x,selected:x===value?true:null},x)));n.value=value||options[0]||'';return n}
if(PAGE==='config'){
 const fixedKeys=['Type','Queue','Service','Owner'];
 const defaults={Type:'Type',Queue:'To queue',Service:'Service',Owner:'Owner'};
 const fields=fixedKeys.map(key=>{const old=CONFIG.fields.find(f=>f.key===key);return old?{...old,label:defaults[key],type:'select',required:true}:{id:'field-'+key.toLowerCase(),key,label:defaults[key],type:'select',values:[],required:true}});
 let linkTypes=[...(CONFIG.linkTypes||[])],apply=null;
 const editOverlay=$('#edit-overlay'),editBody=$('#edit-overlay-body'),editTitle=$('#edit-overlay-title');
 function openList(title,values){editTitle.textContent=title;editBody.replaceChildren();const list=el('div',{class:'fixed-values'});(values||[]).forEach(v=>list.append(el('div',{},v)));editBody.append(list);$('#apply-edit-overlay').classList.add('hidden');editOverlay.classList.remove('hidden')}
 function drawConfig(){const root=$('#config-fields');root.replaceChildren();fields.forEach(f=>{const row=el('div',{class:'compact-row'}),info=el('span');info.append(el('strong',{},f.label),el('small',{},`${f.values.length} Werte · ${f.key}`));const button=el('button',{type:'button'},f.key==='Owner'?'$$Owner':'Werte ansehen');if(f.key==='Owner')button.disabled=true;else button.onclick=()=>openList(f.label,f.values);row.append(info,button);root.append(row)})}
 $('#close-edit-overlay').onclick=()=>editOverlay.classList.add('hidden');drawConfig();
}
const ACTIONS={'ticket-create':'Ticket erstellen','ticket-edit':'Feld ändern','title-edit':'Titel ändern','note':'Textfeld','phone-in':'Phone in','phone-out':'Phone out','email-in':'Email in','email-out':'Email out','email':'E-Mail hinzufügen','phone':'Telefonartikel hinzufügen','customer':'Kunde ändern','queue':'Queue ändern','owner':'Besitzer ändern','responsible':'Verantwortlichen ändern','state':'Status ändern','priority':'Priorität ändern','type':'Typ ändern','service':'Service ändern','sla':'SLA ändern','field-set':'Feld setzen','link':'Verknüpfen','close':'Ticket schließen','free':'Freier Schritt'};
function blankStep(action){return {id:'step-'+crypto.randomUUID(),action,subject:'',body:'',fields:[],links:[],meta:{}}}
function fieldDef(key){return CONFIG.fields.find(f=>f.key===key)||{key,label:key,type:'text',values:[],required:false}}
function valueInput(def,value,onchange,allowVars=true){let n;if(def.type==='select'){n=select(def.values||[],value||(def.values||[])[0]||'');n.addEventListener('change',()=>onchange(n.value));return n}if(def.type==='boolean'){n=select(['','Ja','Nein'],value);n.addEventListener('change',()=>onchange(n.value));return n}if(def.type==='textarea'){n=el('textarea');n.value=value||''}else{const t={number:'number',date:'date',datetime:'datetime-local'}[def.type]||'text';n=el('input',{type:t,value:value||''})}n.addEventListener('input',()=>onchange(n.value));n.addEventListener('change',()=>onchange(n.value));return n}
function addFieldEditor(container,st,forcedKey=null){const key=forcedKey||CONFIG.fields[0]?.key||'',def=fieldDef(key),sf={id:'step-field-'+crypto.randomUUID(),key,value:(def.values||[])[0]||'',enabled:true};st.fields.push(sf);drawSteps()}
let mask=null,openSteps=new Set(['0']);
function relevantKeys(a){return {customer:['CustomerID','CustomerUserID'],queue:['Queue'],owner:['Owner'],responsible:['Responsible'],state:['State','PendingTime'],priority:['Priority'],type:['Type'],service:['Service'],sla:['SLA']}[a]||null}
function ensureActionFields(st){const keys=relevantKeys(st.action);if(keys)keys.forEach(k=>{if(!st.fields.some(f=>f.key===k)&&CONFIG.fields.some(f=>f.key===k))st.fields.push({id:'step-field-'+crypto.randomUUID(),key:k,value:'',enabled:true})})}
function drawFieldRows(box,st,locked=false){st.fields.forEach((sf,fi)=>{const def=fieldDef(sf.key),isStartRequired=st===mask.steps[0]&&['Type','Queue','Service','Owner'].includes(sf.key);sf.enabled=true;if(isStartRequired){if(sf.key==='Owner')return;const row=el('div',{class:'required-field'}),val=valueInput(def,sf.value,v=>sf.value=v);row.append(el('label',{},def.label),val);box.append(row);return}const r=el('div',{class:'row fieldrow'}),key=select(CONFIG.fields.map(f=>f.key),sf.key);if(locked)key.disabled=true;key.onchange=()=>{sf.key=key.value;sf.value=(fieldDef(sf.key).values||[])[0]||'';drawSteps()};const val=valueInput(fieldDef(sf.key),sf.value,v=>sf.value=v),del=el('button',{type:'button',class:'danger'},'Entfernen');del.onclick=()=>{st.fields.splice(fi,1);drawSteps()};r.append(labeled('Znuny-Feld',key,'c4'),labeled('Wert',val,'c6'),labeled('',del,'c2'));box.append(r)})}
function variableNames(text){const out=[],rx=/\$\$([\s\S]{1,120}?)\$\$/g;let m;while((m=rx.exec(text||''))){const name=m[1].trim();if(name&&!out.includes(name))out.push(name)}return out}
function customerPlaceholders(text){const out=[],rx=/\$§([\s\S]{1,500}?)\$§/g;let m;while((m=rx.exec(text||''))){const value=m[1].trim();if(value&&!out.includes(value))out.push(value)}return out}
function openVariable(name){scanVars();const v=mask.variables.find(x=>x.name===name);if(!v)return;const overlay=$('#edit-overlay'),body=$('#edit-overlay-body');$('#edit-overlay-title').textContent='Variable: '+name;body.replaceChildren();const type=select(['text','number','select','random'],['text','number','select','random'].includes(v.type)?v.type:'text'),values=el('textarea',{class:'list-editor'}),prefill=el('input',{type:'text',value:v.prefill||''}),min=el('input',{type:'number',value:v.minimum??''}),max=el('input',{type:'number',value:v.maximum??''}),hidden=el('input',{type:'checkbox',checked:!!v.hidden});values.value=(v.values||[]).join('\n');const typeRow=labeled('Typ',type,'c12'),valuesRow=labeled('Auswahlwerte',values,'c12'),prefillRow=labeled('Vorgabewert',prefill,'c12'),minRow=labeled('Minimum',min,'c6'),maxRow=labeled('Maximum',max,'c6'),hiddenRow=labeled('Hidden',hidden,'c12');function variableVisibility(){valuesRow.classList.toggle('hidden',type.value!=='select');minRow.classList.toggle('hidden',type.value!=='number');maxRow.classList.toggle('hidden',type.value!=='number');prefillRow.classList.toggle('hidden',type.value==='number'||type.value==='random')}type.onchange=variableVisibility;body.append(typeRow,valuesRow,prefillRow,minRow,maxRow,hiddenRow);variableVisibility();$('#apply-edit-overlay').onclick=()=>{v.type=type.value;v.values=[...new Set(values.value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean))];v.prefill=['number','random'].includes(type.value)?'':prefill.value;v.required=false;v.values=type.value==='select'?v.values:[];v.minimum=type.value==='number'&&min.value!==''?Number(min.value):null;v.maximum=type.value==='number'&&max.value!==''?Number(max.value):null;v.hidden=hidden.checked;overlay.classList.add('hidden');status('Variable übernommen')};$('#close-edit-overlay').onclick=()=>overlay.classList.add('hidden');overlay.classList.remove('hidden')}
function textEditor(label,value,onchange,area=true){const wrap=labeled(label,el('div'),'c12'),holder=wrap.lastChild,n=el(area?'textarea':'input',area?{}:{type:'text',maxlength:5000}),chips=el('div',{class:'variable-chips'});n.value=value||'';function refresh(){onchange(n.value);chips.replaceChildren();variableNames(n.value).forEach(name=>{const b=el('button',{type:'button',class:'variable-chip'},'$$'+name+'$$');b.onclick=()=>openVariable(name);chips.append(b)});customerPlaceholders(n.value).forEach(value=>chips.append(el('span',{class:'variable-chip customer-variable-chip'},'$§'+value+'$§')))}n.oninput=refresh;holder.append(n,chips);refresh();return wrap}
function contextMenu(st,index,x,y){document.querySelectorAll('.context-menu').forEach(n=>n.remove());if(index===0)return;const menu=el('div',{class:'context-menu'}),duplicate=el('button',{type:'button'},'Duplizieren'),remove=el('button',{type:'button',class:'danger'},'Löschen');duplicate.onclick=()=>{const c=structuredClone(st);c.id='step-'+crypto.randomUUID();mask.steps.splice(index+1,0,c);menu.remove();drawSteps()};remove.onclick=()=>{mask.steps.splice(index,1);menu.remove();drawSteps()};menu.append(duplicate,remove);menu.style.left=Math.min(x,window.innerWidth-170)+'px';menu.style.top=Math.min(y,window.innerHeight-100)+'px';document.body.append(menu)}
function drawSteps(){const root=$('#steps');root.replaceChildren();mask.steps.forEach((st,i)=>{ensureActionFields(st);const card=el('section',{class:'step','data-index':i}),head=el('div',{class:'step-head'}),title=el('div',{class:'step-title'},`${i+1}. ${ACTIONS[st.action]||'Textfeld'}`);head.append(title);if(i>0){const handle=el('span',{class:'drag-handle',draggable:'true',role:'button',tabindex:'0','aria-label':'Schritt verschieben',title:'Ziehen zum Verschieben'},'⋮⋮');handle.ondragstart=e=>{e.stopPropagation();e.dataTransfer.setData('text/plain',String(i));e.dataTransfer.effectAllowed='move';card.classList.add('dragging')};handle.ondragend=()=>card.classList.remove('dragging');head.append(handle)}card.append(head);card.oncontextmenu=e=>{e.preventDefault();contextMenu(st,i,e.clientX,e.clientY)};if(i>0){card.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='move';card.classList.add('drag-over')};card.ondragleave=()=>card.classList.remove('drag-over');card.ondrop=e=>{e.preventDefault();card.classList.remove('drag-over');const from=Number(e.dataTransfer.getData('text/plain')),to=i;if(from<1||to<1||from===to)return;const [moved]=mask.steps.splice(from,1);mask.steps.splice(to,0,moved);drawSteps()}}
 const body=el('div',{class:'step-body'}),fieldBox=el('div',{class:i===0?'required-fields':''});
 if(st.action==='ticket-create'){drawFieldRows(fieldBox,st,true);body.append(fieldBox)}
 else if(st.action==='ticket-edit'){drawFieldRows(fieldBox,st,false);body.append(fieldBox);const add=el('button',{type:'button',class:'small-add'},'Feldänderung hinzufügen');add.onclick=()=>addFieldEditor(fieldBox,st);body.append(add)}
 if(['ticket-create','note','close'].includes(st.action)){const row=el('div',{class:'row'});row.append(textEditor('Betreff',st.subject,v=>st.subject=v,false),textEditor(st.action==='close'?'Abschlussnotiz':'Text',st.body,v=>st.body=v,true));body.append(row)}
 else if(st.action==='title-edit'){const row=el('div',{class:'row'});row.append(textEditor('Titel',st.subject,v=>st.subject=v,false));body.append(row)}
 else if(['phone-in','phone-out','email-in','email-out'].includes(st.action)){const incoming=st.action.endsWith('-in');st.meta=st.meta||{};const addressRow=el('div',{class:'row'});addressRow.append(textEditor(incoming?'Von':'An',st.meta.address||'',v=>st.meta.address=v,false));body.append(addressRow);const row=el('div',{class:'row'});row.append(textEditor('Betreff',st.subject,v=>st.subject=v,false),textEditor('Text',st.body,v=>st.body=v,true));body.append(row)}
 if(st.action==='link'){const l=st.links[0]||(st.links[0]={id:'link-'+crypto.randomUUID(),object:'Ticket',type:CONFIG.linkTypes[0]||'Normal',direction:'Target',target:''}),r=el('div',{class:'row link-editor'}),obj=select(['Ticket','Gerät'],l.object),typ=select(CONFIG.linkTypes,l.type),tar=el('input',{type:'text',value:l.target,placeholder:'ID, Ticketnummer oder Variable'});obj.onchange=()=>l.object=obj.value;typ.onchange=()=>l.type=typ.value;tar.oninput=()=>l.target=tar.value;r.append(labeled('Ziel',obj,'c3'),labeled('Linktyp',typ,'c3'),labeled('ID / Nummer / Variable',tar,'c6'));body.append(r)}
 card.append(body);root.append(card)});}
function scanVars(){const found=new Set(),rx=/\$\$([\s\S]{1,120}?)\$\$/g;mask.steps.forEach(st=>{[st.subject,st.body,...st.fields.map(f=>f.value),...st.links.map(l=>l.target),...Object.values(st.meta||{})].forEach(t=>{let m;while((m=rx.exec(t||''))){const name=m[1].trim();if(name)found.add(name)}})});found.forEach(name=>{if(!mask.variables.some(v=>v.name===name))mask.variables.push({id:'variable-'+crypto.randomUUID(),name,type:'text',values:[],prefill:'',minimum:null,maximum:null,required:false,hidden:false})});drawVars()}
function drawVars(){}
if(PAGE==='edit'){
 mask=structuredClone(CURRENT);mask.published=true;$('#close-edit-overlay').onclick=()=>$('#edit-overlay').classList.add('hidden');const first=mask.steps[0],fixedKeys=['Type','Queue','Service','Owner'],uniqueFields=[];fixedKeys.forEach(key=>{const existing=first.fields.find(f=>f.key===key),def=fieldDef(key);uniqueFields.push(existing||{id:'step-field-'+crypto.randomUUID(),key,value:key==='Owner'?'$$Owner':'',enabled:true})});first.fields=uniqueFields;first.fields.find(f=>f.key==='Owner').value='$$Owner';$('#mask-name').value=mask.name;$('#mask-name').oninput=()=>mask.name=$('#mask-name').value;$('#mask-yaml-name').value=mask.yamlName||'';$('#mask-yaml-name').oninput=()=>mask.yamlName=$('#mask-yaml-name').value;$('#add-step').onclick=()=>$('#overlay').classList.remove('hidden');$('#close-overlay').onclick=()=>$('#overlay').classList.add('hidden');function addActionStep(key){mask.steps.push(blankStep(key));openSteps.add(String(mask.steps.length-1));$('#overlay').classList.add('hidden');drawSteps()}
 const actionList=$('#action-list');Object.entries(ACTIONS).filter(([k])=>['ticket-edit','title-edit','link','close','note'].includes(k)).forEach(([k,n])=>{const b=el('button',{},n);b.onclick=()=>addActionStep(k);actionList.append(b)});const communication=el('button',{type:'button'},'Phone/email');communication.onclick=()=>{actionList.replaceChildren();[['phone-in','Phone in'],['phone-out','Phone out'],['email-in','Email in'],['email-out','Email out']].forEach(([key,label])=>{const b=el('button',{type:'button'},label);b.onclick=()=>addActionStep(key);actionList.append(b)});const back=el('button',{type:'button'},'Zurück');back.onclick=()=>{actionList.replaceChildren();Object.entries(ACTIONS).filter(([k])=>['ticket-edit','title-edit','link','close','note'].includes(k)).forEach(([k,n])=>{const b=el('button',{},n);b.onclick=()=>addActionStep(k);actionList.append(b)});actionList.append(communication)};actionList.append(back)};actionList.append(communication);$('#save-mask').onclick=async()=>{scanVars();const names=mask.variables.map(v=>v.name.trim());if(names.some((n,i)=>!n||names.indexOf(n)!==i)){status('Variablennamen müssen eindeutig und nicht leer sein.',true);return}const firstStep=mask.steps[0],requiredKeys=['Type','Queue','Service','Owner'];if(!firstStep.subject.trim()||!firstStep.body.trim()||requiredKeys.some(k=>!firstStep.fields.some(f=>f.key===k&&String(f.value).trim()))){status('Im ersten Schritt fehlen Type, To queue, Service, Subject oder Text.',true);return}try{const j=await api({op:'save-mask',mask});status('Maske gespeichert');if(!mask.id)location.href='?page=edit&id='+encodeURIComponent(j.id)}catch(e){status(e.message,true)}};drawSteps();
}
function replaceVars(text,values){return String(text||'').replace(/\$\$([\s\S]+?)\$\$/g,(m,name)=>values[name.trim()]??'').replace(/\$§([\s\S]+?)\$§/g,(m,raw)=>{raw=raw.trim();return /^https?:\/\//i.test(raw)?customerLabel(raw):('Kundeninput: '+raw)})}
function customerLabel(raw){try{const u=new URL(raw),part=decodeURIComponent(u.pathname.split('/').filter(Boolean).pop()||u.hostname);return part.replace(/[-_]+/g,' ')||'Dokument'}catch{return 'Dokument'}}
function hasCopyableText(text){return String(text||'').replace(/\$§[\s\S]+?\$§/g,'').trim()!==''}
function appendRichText(node,text,values){const source=String(text||''),rx=/(\$\$[\s\S]+?\$\$|\$§[\s\S]+?\$§)/g;let pos=0,m;while((m=rx.exec(source))){node.append(document.createTextNode(source.slice(pos,m.index)));const token=m[0];if(token.startsWith('$§')){const raw=token.slice(2,-2).trim();if(/^https?:\/\//i.test(raw))node.append(el('a',{class:'customer-token customer-link',href:raw,target:'_blank',rel:'noopener noreferrer'},customerLabel(raw)));else node.append(el('span',{class:'customer-token'},'Kundeninput: '+raw))}else{const name=token.slice(2,-2).trim();node.append(el('span',{class:'rendered-variable'},values[name]??''))}pos=rx.lastIndex}node.append(document.createTextNode(source.slice(pos)))}
async function copyPlain(text){const value=String(text);try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(value);else{const area=el('textarea');area.value=value;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('copy');area.remove()}status('Text kopiert')}catch{status('Kopieren nicht möglich',true)}}
function copyText(st,values){let out=`${ACTIONS[st.action]}\n`;if(st.subject)out+=`Betreff: ${replaceVars(st.subject,values)}\n`;if(st.body)out+=`\n${replaceVars(st.body,values)}\n`;Object.entries(st.meta||{}).forEach(([k,v])=>{if(v)out+=`${k}: ${replaceVars(v,values)}\n`});(st.links||[]).filter(l=>String(l.target||'').trim()).forEach(l=>out+=`Verknüpfung: ${l.type} ${l.direction} ${replaceVars(l.target,values)}\n`);return out.trim()}
if(PAGE==='view'&&CURRENT){const values={},variableInputs=new Map(),variableTouched=new Set();CURRENT.variables=(CURRENT.variables||[]).filter(v=>v.name!=='Owner');CURRENT.variables.forEach(v=>values[v.name]=v.type==='random'?Array.from({length:5},()=>String.fromCharCode(97+Math.floor(Math.random()*26))).join(''):'');
 function resolveVariableTemplate(text,stack=[]){return String(text??'').replace(/\$\$([\s\S]+?)\$\$/g,(match,name)=>{name=name.trim();if(!name||stack.includes(name))return '';const def=CURRENT.variables.find(v=>v.name===name);if(!def)return values[name]??'';if(def.type==='random')return values[name]??'';if(def.type==='text'&&def.prefill&&variableNames(def.prefill).length)return resolveVariableTemplate(def.prefill,[...stack,name]);return values[name]??resolveVariableTemplate(def.prefill||'',[...stack,name])})}
 CURRENT.variables.forEach(v=>{if(v.type!=='random')values[v.name]=resolveVariableTemplate(v.prefill||'',[v.name])});
 const vr=$('#public-vars');if(!CURRENT.variables.some(v=>!v.hidden)){vr.closest('.public-sidebar').classList.add('hidden');vr.closest('.public-layout').classList.add('no-sidebar')}
 function resolvedOptions(v){return (v.values||[]).map(template=>resolveVariableTemplate(template,[v.name]))}
 function refreshDependentVariables(sourceName=''){CURRENT.variables.forEach(v=>{const input=variableInputs.get(v.name);if(!input)return;if(v.type==='select'){const old=values[v.name],options=resolvedOptions(v);input.replaceChildren();options.forEach(option=>input.append(el('option',{value:option},option)));const prefill=resolveVariableTemplate(v.prefill||'',[v.name]);const next=options.includes(old)?old:(options.includes(prefill)?prefill:(options[0]||''));input.value=next;values[v.name]=next}else if(v.type==='text'&&!variableTouched.has(v.name)&&variableNames(v.prefill||'').length){const next=resolveVariableTemplate(v.prefill||'',[v.name]);input.value=next;values[v.name]=next}});renderPublic()}
 CURRENT.variables.forEach(v=>{const row=el('div',{class:'placeholder-row'}),label=el('label',{class:'placeholder-name'},v.name);let n;if(v.type==='select'){const options=resolvedOptions(v);n=select(options,resolveVariableTemplate(v.prefill||'',[v.name])||options[0]||'');values[v.name]=n.value}else if(v.type==='number')n=el('input',{type:'number',min:v.minimum??'',max:v.maximum??'',value:v.prefill||'',class:'var-input'});else if(v.type==='random')n=el('input',{type:'text',value:values[v.name],class:'var-input',readonly:'readonly'});else n=el('input',{type:'text',value:resolveVariableTemplate(v.prefill||'',[v.name]),class:'var-input'});values[v.name]=n.value;n.setAttribute('aria-label',v.name);n.oninput=n.onchange=()=>{if(v.type==='text')variableTouched.add(v.name);values[v.name]=n.value;refreshDependentVariables(v.name)};variableInputs.set(v.name,n);if(!v.hidden){row.append(label,n);vr.append(row)}});
 function yamlQuote(value){return JSON.stringify(String(value??''))}
 function createValuesYaml(){const lines=['version: 1','mask: '+yamlQuote(CURRENT.id||CURRENT.name||''),'values:'];CURRENT.variables.forEach(v=>lines.push('  '+yamlQuote(v.name)+': '+yamlQuote(values[v.name]??'')));return lines.join('\n')+'\n'}
 function parseValuesYaml(text){if(text.length>131072)throw new Error('YAML-Datei ist zu groß.');const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/),result={},valuesAt=lines.findIndex(line=>/^values:\s*$/.test(line));if(valuesAt<0)throw new Error('YAML enthält keinen values-Bereich.');for(let i=valuesAt+1;i<lines.length;i++){const line=lines[i];if(!line.trim()||/^\s*#/.test(line))continue;if(!/^\s/.test(line))break;const match=line.match(/^\s{2}("(?:\\.|[^"])*"):\s*("(?:\\.|[^"])*")\s*$/);if(!match)throw new Error('Ungültige YAML-Zeile: '+(i+1));const name=JSON.parse(match[1]),value=JSON.parse(match[2]);if(typeof name!=='string'||typeof value!=='string')throw new Error('Ungültiger YAML-Wert in Zeile '+(i+1));result[name]=value}return result}
 function applyImportedValues(imported){CURRENT.variables.forEach(v=>{if(!Object.prototype.hasOwnProperty.call(imported,v.name))return;let value=String(imported[v.name]).slice(0,5000);if(v.type==='select'){if(!(v.values||[]).includes(value))throw new Error('Ungültiger Wert für '+v.name)}else if(v.type==='number'){if(value!==''&&!Number.isFinite(Number(value)))throw new Error('Ungültige Zahl für '+v.name);if(value!==''&&v.minimum!==null&&Number(value)<Number(v.minimum))throw new Error(v.name+' liegt unter dem Minimum.');if(value!==''&&v.maximum!==null&&Number(value)>Number(v.maximum))throw new Error(v.name+' liegt über dem Maximum.')}values[v.name]=value;const input=variableInputs.get(v.name);if(input)input.value=value});renderPublic()}
 if(CURRENT.variables.length){const controls=el('div',{class:'yaml-controls'}),download=el('button',{type:'button',class:'yaml-subtle'},'↓ YAML'),uploadLabel=el('label',{class:'btn yaml-upload yaml-subtle'},'↑ YAML'),upload=el('input',{type:'file',accept:'.yaml,.yml,application/yaml,text/yaml'});upload.classList.add('visually-hidden');download.onclick=()=>{const blob=new Blob([createValuesYaml()],{type:'application/yaml;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a',{href:url,download:(()=>{let name=replaceVars(CURRENT.yamlName||CURRENT.name||'variablen',values).trim().replace(/[^A-Za-z0-9ÄÖÜäöüß._-]+/g,'-').replace(/^-+|-+$/g,'');if(!name)name='variablen';return /\.ya?ml$/i.test(name)?name:name+'.yaml'})()});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),0)};upload.onchange=async()=>{const file=upload.files?.[0];if(!file)return;try{if(file.size>131072)throw new Error('YAML-Datei ist zu groß.');applyImportedValues(parseValuesYaml(await file.text()));status('YAML-Werte geladen')}catch(e){status(e.message||'YAML konnte nicht geladen werden.',true)}finally{upload.value=''}};uploadLabel.append(upload);controls.append(download,uploadLabel);vr.after(controls)}
 function renderPublic(){const root=$('#public-steps');root.replaceChildren();CURRENT.steps.forEach((st,i)=>{const c=el('section',{class:'ticket'}),h=el('h2',{},`${i+1}. ${ACTIONS[st.action]||'Freier Schritt'}`);const body=el('div',{class:'content'});if(['phone-in','phone-out','email-in','email-out'].includes(st.action)&&st.meta?.address){const r=el('div',{class:'kv'}),incoming=st.action.endsWith('-in');const addressValue=el('span');appendRichText(addressValue,st.meta.address,values);r.append(el('strong',{},incoming?'Von':'An'),addressValue);body.append(r)}(st.fields||[]).filter(f=>f.enabled&&!(i===0&&f.key==='Owner')).forEach(f=>{const r=el('div',{class:'kv'});const valueBox=el('span');appendRichText(valueBox,f.value,values);r.append(el('strong',{},fieldDef(f.key).label),valueBox);body.append(r)});if(st.subject){const subject=replaceVars(st.subject,values),line=el('div',{class:'text-block'});const subjectBox=el('div',{class:'copyable'});appendRichText(subjectBox,st.subject,values);line.append(el('strong',{},st.action==='title-edit'?'Titel':'Betreff'),subjectBox);if(hasCopyableText(st.subject)){const b=el('button',{class:'copy-inline'},st.action==='title-edit'?'Titel kopieren':'Betreff kopieren');b.onclick=()=>copyPlain(subject);line.append(b)}body.append(line)}if(st.body){const wrap=el('div',{class:'text-block'});wrap.append(el('strong',{},'Text'));const p=el('div',{class:'copyable'});String(st.body||'').split('\n').forEach((line,j)=>{if(j)p.append(document.createElement('br'));appendRichText(p,line,values)});wrap.append(p);if(hasCopyableText(st.body)){const b=el('button',{class:'copy-inline'},'Text kopieren');b.onclick=()=>copyPlain(replaceVars(st.body,values));wrap.append(b)}body.append(wrap)};(st.links||[]).filter(l=>String(l.target||'').trim()).forEach(l=>{const r=el('div',{class:'kv'});const linkValue=el('span');linkValue.append(document.createTextNode(l.type+' · '));appendRichText(linkValue,l.target,values);r.append(el('strong',{},'Verknüpfung'),linkValue);body.append(r)});c.append(h,body);root.append(c)})}renderPublic();}
